<template>
  <div class="logistica-page">
    <v-card class="mb-5 rounded-xl" elevation="0" border>
      <v-card-text class="pa-4 d-flex flex-wrap align-center ga-3">
        <v-icon :icon="tab === 'kardex' ? 'mdi-history' : tab === 'configuracion' ? 'mdi-cog-outline' : 'mdi-clipboard-list-outline'" color="primary" size="28"/>
        <div>
          <div class="text-h6 font-weight-bold">{{ tab === 'kardex' ? 'Kardex' : tab === 'configuracion' ? 'Configuración logística' : 'Inventario' }}</div>
          <div class="text-body-2 text-medium-emphasis">{{ tab === 'kardex' ? 'Historial de movimientos por almacén' : tab === 'configuracion' ? 'Opciones globales de la empresa' : 'Existencias y mínimos por almacén' }}<span v-if="tab !== 'configuracion'"> · {{ branch.sucursalActual?.nombre || 'Selecciona una sucursal' }}</span></div>
        </div>
        <v-spacer/>
        <v-btn v-if="canManage && tab === 'existencias' && branch.idSucursalActual" color="primary" prepend-icon="mdi-plus" rounded="lg" @click="openCreate">Nuevo inventario</v-btn>
        <v-btn v-if="canManage && tab === 'kardex' && branch.idSucursalActual" color="primary" prepend-icon="mdi-swap-vertical" rounded="lg" @click="openMove()">Registrar movimiento</v-btn>
      </v-card-text>
    </v-card>
    <v-alert v-if="error" type="error" variant="tonal" closable class="mb-4" @click:close="error = ''">{{ error }}</v-alert><v-alert v-if="!branch.idSucursalActual && tab !== 'configuracion'" type="info" variant="tonal" class="mb-4">Selecciona una sucursal para consultar sus existencias.</v-alert>
    <v-card v-if="tab === 'kardex'" class="mb-4 rounded-xl" elevation="0" border>
      <v-card-text class="pa-4 d-flex flex-wrap align-center ga-3">
        <v-text-field v-model="fromDate" type="date" label="Desde" variant="outlined" density="comfortable" hide-details class="logistica-filter"/>
        <v-text-field v-model="toDate" type="date" label="Hasta" variant="outlined" density="comfortable" hide-details class="logistica-filter"/>
        <v-btn v-if="fromDate || toDate" variant="text" color="primary" @click="fromDate = ''; toDate = ''">Limpiar fechas</v-btn>
      </v-card-text>
    </v-card>
    <template v-if="tab !== 'configuracion'"><v-card class="mb-4 rounded-xl" elevation="0" border><v-card-text class="pa-4"><div class="logistica-toolbar"><v-text-field v-model="search" class="logistica-search" placeholder="Buscar producto..." prepend-inner-icon="mdi-magnify" variant="outlined" density="comfortable" rounded="lg" clearable hide-details @update:model-value="scheduleSearch" @keyup.enter="searchNow"/><v-select v-model="warehouseId" class="logistica-filter" :items="warehouseFilters" item-title="nombre" item-value="idAlmacen" label="Almacén" variant="outlined" density="comfortable" rounded="lg" hide-details/><v-select v-if="tab === 'kardex'" v-model="movementTypeId" class="logistica-filter" :items="movementFilters" item-title="nombre" item-value="idTipoMovimiento" label="Movimiento" variant="outlined" density="comfortable" rounded="lg" hide-details/><v-btn icon="mdi-refresh" color="primary" variant="tonal" rounded="lg" :loading="loading" aria-label="Actualizar inventario" @click="load"/><span class="logistica-count"><v-icon size="19">mdi-format-list-numbered</v-icon>{{ total }} registros</span></div></v-card-text></v-card><v-card rounded="xl" elevation="0" border class="overflow-hidden"><div v-if="loading" class="text-center py-14"><v-progress-circular indeterminate color="primary"/></div><template v-else-if="items.length && tab === 'existencias'"><v-table hover class="logistica-table logistica-desktop"><thead><tr><th>Producto</th><th>Almacén</th><th>Precio venta</th><th>Stock</th><th>Mínimo</th><th>Estado</th><th class="text-end">Acciones</th></tr></thead><tbody><tr v-for="item in inventoryRows" :key="item.idInventario"><td><strong>{{ item.productoSucursal?.producto?.nombre }}</strong><div class="text-caption text-medium-emphasis">{{ item.productoSucursal?.producto?.unidadMedida?.simbolo }}</div></td><td>{{ item.almacen?.nombre }}</td><td>S/ {{ money(item.productoSucursal?.precioVenta) }}</td><td :class="Number(item.stock)<0?'text-error font-weight-bold':'font-weight-bold'">{{ quantity(item.stock) }}</td><td>{{ quantity(item.stockMinimo) }}</td><td><v-chip size="small" :color="stockColor(item)" variant="tonal">{{ stockLabel(item) }}</v-chip></td><td class="text-end text-no-wrap"><v-btn v-if="canManage" icon="mdi-swap-vertical" size="small" variant="text" color="primary" :aria-label="`Mover ${item.productoSucursal?.producto?.nombre}`" @click="openMove(item)"/><v-btn v-if="canManage" icon="mdi-pencil-outline" size="small" variant="text" color="primary" :aria-label="`Editar mínimo de ${item.productoSucursal?.producto?.nombre}`" @click="openMinimum(item)"/></td></tr></tbody></v-table><div class="logistica-mobile pa-3"><v-card v-for="item in inventoryRows" :key="item.idInventario" variant="outlined" rounded="lg" class="mb-3"><v-card-text class="pa-3"><div class="d-flex align-center ga-3"><v-avatar color="primary" variant="tonal"><v-icon icon="mdi-package-variant"/></v-avatar><div class="flex-grow-1"><strong>{{ item.productoSucursal?.producto?.nombre }}</strong><div class="text-caption">{{ item.almacen?.nombre }} · mínimo {{ quantity(item.stockMinimo) }}</div></div><div class="text-right"><div class="font-weight-bold">{{ quantity(item.stock) }}</div><v-chip size="x-small" :color="stockColor(item)" variant="tonal">{{ stockLabel(item) }}</v-chip></div></div><div v-if="canManage" class="d-flex justify-end mt-2"><v-btn size="small" variant="text" color="primary" @click="openMove(item)">Movimiento</v-btn><v-btn size="small" variant="text" color="primary" @click="openMinimum(item)">Mínimo</v-btn></div></v-card-text></v-card></div></template><template v-else-if="items.length && tab === 'kardex'"><v-table hover class="logistica-table logistica-desktop"><thead><tr><th>Fecha</th><th>Producto / almacén</th><th>Tipo</th><th>Cantidad</th><th>Antes → después</th><th>Observación</th></tr></thead><tbody><tr v-for="item in movementRows" :key="item.idMovimiento"><td>{{ dateTime(item.fechaMovimiento) }}</td><td><strong>{{ item.inventario?.productoSucursal?.producto?.nombre }}</strong><div class="text-caption text-medium-emphasis">{{ item.inventario?.almacen?.nombre }}</div></td><td><v-chip size="small" :color="item.tipoMovimiento?.entradaSalida === 'ENTRADA' ? 'success' : 'warning'" variant="tonal">{{ item.tipoMovimiento?.nombre }}</v-chip></td><td :class="item.tipoMovimiento?.entradaSalida === 'ENTRADA' ? 'text-success' : 'text-warning'" class="font-weight-bold">{{ item.tipoMovimiento?.entradaSalida === 'ENTRADA' ? '+' : '−' }}{{ quantity(item.cantidad) }}</td><td>{{ quantity(item.stockAnterior) }} → {{ quantity(item.stockResultante) }}</td><td>{{ item.observacion || '—' }}</td></tr></tbody></v-table><div class="logistica-mobile pa-3"><v-card v-for="item in movementRows" :key="item.idMovimiento" variant="outlined" rounded="lg" class="mb-3"><v-card-text class="pa-3"><div class="d-flex justify-space-between ga-2"><div><strong>{{ item.inventario?.productoSucursal?.producto?.nombre }}</strong><div class="text-caption">{{ item.inventario?.almacen?.nombre }} · {{ dateTime(item.fechaMovimiento) }}</div></div><v-chip size="x-small" :color="item.tipoMovimiento?.entradaSalida === 'ENTRADA' ? 'success' : 'warning'" variant="tonal">{{ item.tipoMovimiento?.nombre }}</v-chip></div><div class="mt-2">{{ quantity(item.stockAnterior) }} → <strong>{{ quantity(item.stockResultante) }}</strong> · {{ item.observacion || 'Sin observación' }}</div></v-card-text></v-card></div></template><div v-else class="logistica-empty"><v-icon :icon="tab === 'kardex' ? 'mdi-history' : 'mdi-package-variant'" size="48" class="mb-3"/><div>{{ tab === 'kardex' ? 'No hay movimientos' : 'No se encontraron existencias' }}</div></div><v-divider/><div class="d-flex align-center justify-space-between pa-3"><span class="text-caption text-medium-emphasis">Mostrando {{ items.length }} de {{ total }}</span><v-pagination v-if="total > limit" v-model="page" :length="Math.ceil(total / limit)" :total-visible="5" size="small" color="primary"/></div></v-card></template>
    <v-card v-else rounded="xl" elevation="0" border><v-card-title class="pa-5"><v-icon icon="mdi-cog-outline" color="primary" class="mr-2"/>Configuración global</v-card-title><v-divider/><v-card-text class="pa-5"><v-alert type="info" variant="tonal" class="mb-5">Este ajuste afecta a todas las sucursales. Los saldos negativos existentes se conservan si luego lo desactivas.</v-alert><div class="d-flex justify-space-between align-center ga-4"><div><div class="font-weight-bold">Permitir stock negativo</div><div class="text-body-2 text-medium-emphasis">Permite registrar salidas aunque el saldo quede bajo cero.</div></div><v-switch :model-value="negativeStock" color="primary" hide-details :loading="configLoading" :disabled="!canManage || configLoading" aria-label="Permitir stock negativo" @update:model-value="changeNegativeStock"/></div></v-card-text></v-card>
    <v-dialog v-model="createDialog" max-width="600" persistent><v-card rounded="xl" class="overflow-hidden"><v-card-title class="logistica-dialog-title"><span class="logistica-dialog-icon"><v-icon icon="mdi-plus"/></span>Nuevo inventario<v-spacer/><v-btn icon="mdi-close" variant="text" color="on-primary" @click="createDialog = false"/></v-card-title><v-card-text class="pa-5"><v-alert v-if="formError" type="error" variant="tonal" class="mb-4">{{ formError }}</v-alert><div class="text-body-2 text-medium-emphasis mb-4">Sucursal: {{ branch.sucursalActual?.nombre }}</div><label class="logistica-field-label">Producto asignado a la sucursal *</label><v-autocomplete v-model="createForm.idProductoSucursal" :items="assignments" :item-title="(item: ProductoSucursal) => item.producto?.nombre || `Producto #${item.idProducto}`" item-value="idProductoSucursal" placeholder="Selecciona un producto" variant="outlined" density="comfortable"/><label class="logistica-field-label">Almacén *</label><v-select v-model="createForm.idAlmacen" :items="warehouses.filter(item => item.estado)" item-title="nombre" item-value="idAlmacen" placeholder="Selecciona un almacén" variant="outlined" density="comfortable"/><v-row dense><v-col cols="12" sm="6"><label class="logistica-field-label">Stock inicial</label><v-text-field v-model="createForm.stockInicial" type="number" step="0.001" min="0" variant="outlined" density="comfortable"/></v-col><v-col cols="12" sm="6"><label class="logistica-field-label">Stock mínimo</label><v-text-field v-model="createForm.stockMinimo" type="number" step="0.001" min="0" variant="outlined" density="comfortable"/></v-col></v-row><v-alert type="info" variant="tonal" density="compact">El stock inicial quedará registrado como movimiento en el kardex.</v-alert></v-card-text><v-divider/><v-card-actions class="pa-4"><v-spacer/><v-btn variant="text" @click="createDialog = false">Cancelar</v-btn><v-btn color="primary" :loading="saving" @click="saveCreate">Guardar</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="minimumDialog" max-width="450"><v-card rounded="xl" class="overflow-hidden"><v-card-title class="logistica-dialog-title"><span class="logistica-dialog-icon"><v-icon icon="mdi-pencil-outline"/></span>Stock mínimo<v-spacer/><v-btn icon="mdi-close" variant="text" color="on-primary" @click="minimumDialog = false"/></v-card-title><v-card-text class="pa-5"><v-alert v-if="formError" type="error" variant="tonal" class="mb-4">{{ formError }}</v-alert><div class="font-weight-bold mb-3">{{ selectedInventory?.productoSucursal?.producto?.nombre }} · {{ selectedInventory?.almacen?.nombre }}</div><label class="logistica-field-label">Nuevo mínimo</label><v-text-field v-model="minimumValue" type="number" step="0.001" min="0" variant="outlined" density="comfortable"/></v-card-text><v-card-actions class="pa-4"><v-spacer/><v-btn variant="text" @click="minimumDialog = false">Cancelar</v-btn><v-btn color="primary" :loading="saving" @click="saveMinimum">Guardar</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog v-model="moveDialog" max-width="600" persistent><v-card rounded="xl" class="overflow-hidden"><v-card-title class="logistica-dialog-title"><span class="logistica-dialog-icon"><v-icon icon="mdi-swap-vertical"/></span>Registrar movimiento<v-spacer/><v-btn icon="mdi-close" variant="text" color="on-primary" @click="moveDialog = false"/></v-card-title><v-card-text class="pa-5"><v-alert v-if="formError" type="error" variant="tonal" class="mb-4">{{ formError }}</v-alert><label class="logistica-field-label">Producto / almacén *</label><v-autocomplete v-model="moveForm.idInventario" :items="inventoryOptions" :item-title="(item: Inventario) => `${item.productoSucursal?.producto?.nombre} · ${item.almacen?.nombre} (stock ${quantity(item.stock)})`" item-value="idInventario" placeholder="Selecciona una existencia" variant="outlined" density="comfortable"/><label class="logistica-field-label">Tipo de movimiento *</label><v-select v-model="moveForm.idTipoMovimiento" :items="movementTypes.filter(item => item.idTipoMovimiento !== 1)" item-title="nombre" item-value="idTipoMovimiento" placeholder="Selecciona el tipo" variant="outlined" density="comfortable"/><label class="logistica-field-label">Cantidad *</label><v-text-field v-model="moveForm.cantidad" type="number" step="0.001" min="0.001" variant="outlined" density="comfortable"/><label class="logistica-field-label">Observación</label><v-textarea v-model="moveForm.observacion" placeholder="Motivo del ajuste o merma" variant="outlined" density="comfortable" rows="2" auto-grow/><v-alert type="info" variant="tonal" density="compact">El movimiento no se puede editar ni eliminar. Una corrección se registra con otro ajuste.</v-alert></v-card-text><v-divider/><v-card-actions class="pa-4"><v-spacer/><v-btn variant="text" @click="moveDialog = false">Cancelar</v-btn><v-btn color="primary" :loading="saving" @click="saveMove">Registrar</v-btn></v-card-actions></v-card></v-dialog>
    <v-snackbar v-model="noticeVisible" color="success">{{ notice }}</v-snackbar>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { getApiErrorMessage } from '@/core/api/api-error'
import { Permiso } from '@/core/constants/permisos'
import { useAuthStore } from '@/modules/auth/auth.store'
import { useSucursalStore } from '@/shared/stores/sucursal.store'
import { almacenesApi, configuracionesApi, inventariosApi, productoSucursalApi } from '../logistica.api'
import type { Almacen, Inventario, MovimientoInventario, ProductoSucursal, TipoMovimiento } from '../logistica.types'
import '../logistica.css'
const auth=useAuthStore(),branch=useSucursalStore(),canManage=computed(()=>auth.puede(Permiso.LOGISTICA_GESTIONAR))
const route=useRoute()
const tab=computed(() => route.name === 'logistica-kardex' ? 'kardex' : route.name === 'logistica-configuracion' ? 'configuracion' : 'existencias')
const items=ref<(Inventario|MovimientoInventario)[]>([]),total=ref(0),page=ref(1),limit=50,search=ref(''),warehouseId=ref<number|null>(null),movementTypeId=ref<number|null>(null),fromDate=ref(''),toDate=ref('')
const warehouses=ref<Almacen[]>([]),assignments=ref<ProductoSucursal[]>([]),movementTypes=ref<TipoMovimiento[]>([]),inventoryOptions=ref<Inventario[]>([])
const warehouseFilters=computed(()=>[{idAlmacen:null,nombre:'Todos los almacenes'},...warehouses.value]),movementFilters=computed(()=>[{idTipoMovimiento:null,nombre:'Todos los movimientos'},...movementTypes.value])
const inventoryRows=computed(()=>items.value as Inventario[]),movementRows=computed(()=>items.value as MovimientoInventario[])
const loading=ref(false),saving=ref(false),configLoading=ref(false),negativeStock=ref(false),createDialog=ref(false),minimumDialog=ref(false),moveDialog=ref(false),selectedInventory=ref<Inventario|null>(null)
const error=ref(''),formError=ref(''),notice=ref(''),noticeVisible=ref(false),minimumValue=ref('0'),createForm=reactive({idProductoSucursal:null as number|null,idAlmacen:null as number|null,stockInicial:'0',stockMinimo:'0'}),moveForm=reactive({idInventario:null as number|null,idTipoMovimiento:null as number|null,cantidad:'',observacion:''})
let timer:ReturnType<typeof setTimeout>|undefined,requestId=0
function quantity(value:string|undefined){const n=Number(value??0);return Number.isFinite(n)?new Intl.NumberFormat('es-PE',{maximumFractionDigits:3}).format(n):'0'}
function money(value:string|undefined){const n=Number(value??0);return Number.isFinite(n)?n.toFixed(2):'0.00'}
function dateTime(value:string){return new Intl.DateTimeFormat('es-PE',{dateStyle:'short',timeStyle:'short'}).format(new Date(value))}
function stockColor(item:Inventario){return Number(item.stock)<0?'error':Number(item.stock)<=Number(item.stockMinimo)?'warning':'success'}
function stockLabel(item:Inventario){return Number(item.stock)<0?'Negativo':Number(item.stock)<=Number(item.stockMinimo)?'Bajo mínimo':'Disponible'}
async function load(){const current=++requestId;if(!branch.idSucursalActual||tab.value==='configuracion'){items.value=[];total.value=0;loading.value=false;return}loading.value=true;error.value='';try{const params={pagina:page.value,limite:limit,idSucursal:branch.idSucursalActual,idAlmacen:warehouseId.value??undefined,buscar:search.value.trim()||undefined};const {data}=tab.value==='existencias'?await inventariosApi.listar(params):await inventariosApi.movimientos({...params,idTipoMovimiento:movementTypeId.value??undefined,desde:fromDate.value?`${fromDate.value}T00:00:00-05:00`:undefined,hasta:toDate.value?`${toDate.value}T23:59:59-05:00`:undefined});if(current===requestId){items.value=data.data;total.value=data.total}}catch(cause){if(current===requestId)error.value=getApiErrorMessage(cause,'No se pudo cargar el inventario')}finally{if(current===requestId)loading.value=false}}
function searchNow(){if(timer)clearTimeout(timer);if(page.value!==1)page.value=1;else void load()}
function scheduleSearch(){if(timer)clearTimeout(timer);timer=setTimeout(searchNow,350)}
async function loadAll<T>(fn:(page:number)=>Promise<{data:{data:T[];total:number}}>){const out:T[]=[];let p=1,total=0;do{const result=await fn(p);out.push(...result.data.data);total=result.data.total;p++}while(out.length<total);return out}
async function loadOptions(){if(!branch.idSucursalActual){warehouses.value=[];assignments.value=[];inventoryOptions.value=[];return}const id=branch.idSucursalActual;try{const [w,a,i]=await Promise.all([loadAll(p=>almacenesApi.listar({idSucursal:id,pagina:p,limite:100})),loadAll(p=>productoSucursalApi.listar({idSucursal:id,estado:true,pagina:p,limite:100})),loadAll(p=>inventariosApi.listar({idSucursal:id,pagina:p,limite:100}))]);if(branch.idSucursalActual===id){warehouses.value=w;assignments.value=a;inventoryOptions.value=i}}catch(cause){error.value=getApiErrorMessage(cause,'No se pudieron cargar los datos de la sucursal')}}
async function loadTypes(){try{movementTypes.value=(await inventariosApi.tiposMovimiento()).data}catch(cause){error.value=getApiErrorMessage(cause,'No se pudieron cargar los tipos de movimiento')}}
async function loadConfig(){if(!auth.esSuperadmin)return;configLoading.value=true;try{negativeStock.value=(await configuracionesApi.listar()).data.find(x=>x.nombre==='STOCK_NEGATIVO')?.activo??false}catch(cause){error.value=getApiErrorMessage(cause,'No se pudo cargar la configuración')}finally{configLoading.value=false}}
async function changeNegativeStock(value:boolean|null){if(value===null)return;configLoading.value=true;error.value='';try{const {data}=await configuracionesApi.actualizar('STOCK_NEGATIVO',value);negativeStock.value=data.activo;notice.value='Configuración actualizada';noticeVisible.value=true}catch(cause){error.value=getApiErrorMessage(cause,'No se pudo actualizar la configuración')}finally{configLoading.value=false}}
const validNonnegative=(value:string)=>/^\d+(\.\d{1,3})?$/.test(value)&&Number.isFinite(Number(value))
function openCreate(){Object.assign(createForm,{idProductoSucursal:null,idAlmacen:null,stockInicial:'0',stockMinimo:'0'});formError.value='';createDialog.value=true;void loadOptions()}
async function saveCreate(){if(!createForm.idProductoSucursal||!createForm.idAlmacen||!validNonnegative(createForm.stockInicial)||!validNonnegative(createForm.stockMinimo)){formError.value='Selecciona producto y almacén e ingresa cantidades válidas (máximo 3 decimales)';return}saving.value=true;formError.value='';try{await inventariosApi.crear({idProductoSucursal:createForm.idProductoSucursal,idAlmacen:createForm.idAlmacen,stockInicial:createForm.stockInicial,stockMinimo:createForm.stockMinimo});createDialog.value=false;notice.value='Inventario creado';noticeVisible.value=true;await Promise.all([load(),loadOptions()])}catch(cause){formError.value=getApiErrorMessage(cause,'No se pudo crear el inventario')}finally{saving.value=false}}
function openMinimum(item:Inventario){selectedInventory.value=item;minimumValue.value=item.stockMinimo;formError.value='';minimumDialog.value=true}
async function saveMinimum(){if(!selectedInventory.value||!validNonnegative(minimumValue.value)){formError.value='Ingresa un mínimo válido (máximo 3 decimales)';return}saving.value=true;formError.value='';try{await inventariosApi.actualizarMinimo(selectedInventory.value.idInventario,minimumValue.value);minimumDialog.value=false;notice.value='Stock mínimo actualizado';noticeVisible.value=true;await load()}catch(cause){formError.value=getApiErrorMessage(cause,'No se pudo actualizar el mínimo')}finally{saving.value=false}}
function openMove(item?:Inventario){Object.assign(moveForm,{idInventario:item?.idInventario??null,idTipoMovimiento:null,cantidad:'',observacion:''});formError.value='';moveDialog.value=true;void Promise.all([loadOptions(),loadTypes()])}
async function saveMove(){if(!moveForm.idInventario||!moveForm.idTipoMovimiento||!validNonnegative(moveForm.cantidad)||Number(moveForm.cantidad)<=0){formError.value='Selecciona inventario, tipo e ingresa una cantidad positiva';return}saving.value=true;formError.value='';try{await inventariosApi.mover({idInventario:moveForm.idInventario,idTipoMovimiento:moveForm.idTipoMovimiento,cantidad:moveForm.cantidad,observacion:moveForm.observacion.trim()||null});moveDialog.value=false;notice.value='Movimiento registrado';noticeVisible.value=true;await Promise.all([load(),loadOptions()])}catch(cause){formError.value=getApiErrorMessage(cause,'No se pudo registrar el movimiento')}finally{saving.value=false}}
watch([tab,warehouseId,movementTypeId,fromDate,toDate,()=>branch.idSucursalActual],()=>{if(page.value!==1)page.value=1;else void load()});watch(()=>branch.idSucursalActual,()=>{warehouseId.value=null;void loadOptions()});watch(tab,value=>{if(value==='configuracion')void loadConfig()});watch(page,load,{immediate:true});onMounted(()=>{void loadOptions();void loadTypes();void loadConfig()});onUnmounted(()=>{if(timer)clearTimeout(timer);requestId++})
</script>
